bool isValidSscc(String sscc) {
  if (!RegExp(r'^\d{18}$').hasMatch(sscc)) return false;
  final body = sscc.substring(0, 17);
  final check = int.parse(sscc[17]);
  int sum = 0;
  for (int i = 0; i < body.length; i++) {
    final digit = int.parse(body[body.length - 1 - i]);
    sum += (i.isEven ? 3 : 1) * digit;
  }
  return (10 - sum % 10) % 10 == check;
}

// Barcode-embed via AI (00):
// GS1-128 element string: `(00)389012340123456787`
// Parenthesis notation for humans; group-separator ASCII 29 between AIs on machines.

String ssccElement(String sscc) => '(00)$sscc';

// SSCC URN (EPCIS):
// urn:epc:id:sscc:GCP.extensionAndSerial
String ssccUrn({required String gcp, required String extAndSerial}) =>
    'urn:epc:id:sscc:$gcp.$extAndSerial';

